import{_ as r,r as l,c as e,g as a,a as c,F as d,h as u,o as n,t as s}from"./index-5hXIG5--.js";const v={class:"how-and-why-page"},m={class:"section content-section"},y={class:"responsive-container"},p={class:"content-article"},h={class:"coordinators-section"},b={class:"university-name"},f={class:"coordinator-name"},g=["href"],k={__name:"HowAndWhyView",setup(w){const o=l([{id:1,university:"Eurasian Technological University (ETU), Almaty",name:"Talgat Zhuniskaliyev",email:"t.zhuniskaliyev@etu.edu.kz"},{id:2,university:"Karaganda Industrial University (KarIU), Temirtau",name:"Anatassiya Chvanova",email:"a.chvanova@tttu.edu.kz"},{id:3,university:"Bishkek State University (BSU), Bishkek",name:"Elegiia Bokovea",email:"elegiabokoeva@gmail.com"},{id:4,university:"University of Central Asia – Kyrgyz Republic and Tajikistan (UCAK/T), Naryn and Khorog",name:"Kanat Telikeyev",email:"kanat.tilekeyev@ucentralasia.org"},{id:5,university:"Khorog State University (KSU), Tajikistan",name:"Tojigul Mardonova",email:"tojigulmardonova@gmail.com"},{id:6,university:"International Oil and Gas University (IOGU), Turkmenistan",name:"Nazarmuhammet Nazargulyyev",email:"nazargulyyewnazar05@gmail.com"},{id:7,university:"International Horse Breeding Academy (IHBA), Turkmenistan",name:"Begmyradov Dovran",email:"dovran.ihba@gmail.com"},{id:8,university:"Tashkent Institute of Irrigation and Agricultural Mechanization Engineers (TIIAME), Uzbekistan",name:"Sherzod Rakhmonov",email:"sherzod.rakhmonov@gmail.com"},{id:9,university:"Tashkent Kimyo International University (KIUT), Uzbekistan",name:"Madumar Musurmonov",email:"madumar94@mail.ru"}]);return(U,i)=>(n(),e("main",v,[i[2]||(i[2]=a("section",{class:"hero-section"},[a("div",{class:"hero-content"},[a("h1",{class:"hero-title"},"How and Why to Study Sustainability at Your University")])],-1)),a("section",m,[a("div",y,[a("article",p,[i[1]||(i[1]=c('<p class="lead-text" data-v-c9bf7056> Understanding sustainability today means learning how social, ecological, and economic systems interact—and how we can move from simply reducing harm to regenerating the living systems we depend on. This page helps you understand why sustainability and regenerative studies matter, and how you can build your own learning path within the GDCAU network. </p><div class="content-block" data-v-c9bf7056><h2 class="content-title" data-v-c9bf7056>Why Study Sustainability and Regeneration?</h2><p data-v-c9bf7056> Sustainability issues—climate change, water scarcity, biodiversity loss, pollution, and rapid urbanization—directly shape life across Central Asia. </p><p data-v-c9bf7056> Studying sustainability helps you: </p><ul class="benefits-list" data-v-c9bf7056><li data-v-c9bf7056>understand how environmental and social systems are connected</li><li data-v-c9bf7056>develop skills for solving complex real-world problems</li><li data-v-c9bf7056>contribute to the resilience and regeneration of your community</li><li data-v-c9bf7056>prepare for growing green and ESG career opportunities</li><li data-v-c9bf7056>participate in shaping a healthier, fairer, and more stable future</li></ul><p data-v-c9bf7056> Regeneration goes a step further: it focuses not only on minimizing negative impacts, but on repairing ecosystems, restoring relationships, and strengthening the capacity of communities and landscapes to thrive. </p></div><div class="content-block" data-v-c9bf7056><h2 class="content-title" data-v-c9bf7056>How to Study Sustainability at Your University</h2><p data-v-c9bf7056> Sustainability learning at GDCAU is flexible, modular, and student-centered. You can explore sustainability through: </p><ul class="study-options-list" data-v-c9bf7056><li data-v-c9bf7056>courses at your home university</li><li data-v-c9bf7056>modules and short courses offered by GDCAU partners</li><li data-v-c9bf7056>interdisciplinary or project-based learning</li><li data-v-c9bf7056>community engagement and regenerative campus initiatives</li><li data-v-c9bf7056>micro-credentials and mobility opportunities</li></ul><p data-v-c9bf7056> The GDCAU network makes it possible to mix and match learning experiences in ways that work for your academic path and personal interests. </p></div><div class="content-block" data-v-c9bf7056><h2 class="content-title" data-v-c9bf7056>Individual Learning Pathways</h2><p data-v-c9bf7056> As outlined in the GDCAU Framework for Individual Learning Paths, students can design a personalized sustainability study plan that may include: </p><ul class="pathways-list" data-v-c9bf7056><li data-v-c9bf7056>Green Deal and ESG-focused modules</li><li data-v-c9bf7056>elective courses from different disciplines</li><li data-v-c9bf7056>micro-credentials (e.g., green literacy, circular economy)</li><li data-v-c9bf7056>short-term mobility between partner universities</li><li data-v-c9bf7056>research or project-based activities</li><li data-v-c9bf7056>internships or field-based learning</li></ul><p data-v-c9bf7056> Your learning path is flexible and fully supported by your university&#39;s academic regulations. </p><p class="highlight-text" data-v-c9bf7056> Get in touch with your university&#39;s GDC Hub Coordinator to discuss your options. </p></div><div class="content-block" data-v-c9bf7056><h2 class="content-title" data-v-c9bf7056>Your GDC Hub Coordinator (Academic Advisor)</h2><p data-v-c9bf7056> Each university has a GDC Hub Coordinator who supports students in planning and navigating their sustainability studies as described in the GDCAU Students&#39; Support Framework. </p><p data-v-c9bf7056> Your coordinator can help you: </p><ul class="coordinator-help-list" data-v-c9bf7056><li data-v-c9bf7056>plan an individual learning pathway</li><li data-v-c9bf7056>choose appropriate courses or micro-credentials</li><li data-v-c9bf7056>explore exchange or mobility options</li><li data-v-c9bf7056>find campus or community projects to join</li><li data-v-c9bf7056>get academic or administrative support as needed</li></ul><p data-v-c9bf7056> A full list of coordinators appears just below on this page. </p></div><div class="content-block ready-block" data-v-c9bf7056><h2 class="content-title" data-v-c9bf7056>Ready to Begin?</h2><p class="ready-text" data-v-c9bf7056> Studying sustainability and regeneration is not just an academic choice—it&#39;s a way of learning to act, collaborate, and create solutions that support thriving ecosystems and communities. </p><p class="ready-text highlight" data-v-c9bf7056> Your journey starts here! </p></div>',6)),a("div",h,[i[0]||(i[0]=a("h2",{class:"coordinators-title"},"Here's your local coordinator's contact information:",-1)),(n(!0),e(d,null,u(o.value,t=>(n(),e("div",{class:"coordinator-card",key:t.id},[a("h3",b,s(t.university),1),a("p",f,s(t.name),1),a("a",{href:`mailto:${t.email}`,class:"coordinator-email"},s(t.email),9,g)]))),128))])])])])]))}},A=r(k,[["__scopeId","data-v-c9bf7056"]]);export{A as default};
